#include <iostream>
#include <vector>
#include <stack> // added for iterative DFS
using namespace std;

bool visit[26];
vector<int> g[26]; // adjacency list

bool dfs(int v) {
    stack<int> s;
    s.push(v);
    visit[v] = true;
    bool f = false;

    while (!s.empty()) {
        int curr = s.top();
        s.pop();
        for (int i : g[curr]) {
            if (!visit[i]) {
                visit[i] = true;
                s.push(i);
                f = true;
            }
        }
    }
    return f;
}

int graph_num(void) {
    int res = 0;
    for (int i = 0; i < 26; i++)
        if (!visit[i] && dfs(i)) res++;
    return res;
}

int main() {
    int n, pre[26], suf[26], h, t;
    string s;

    while (cin >> n && n) {
        fill(begin(visit), end(visit), false);
        fill(begin(pre), end(pre), 0);
        fill(begin(suf), end(suf), 0);

        for (int i = 0; i < 26; i++) g[i].clear();

        for (int i = 0; i < n; i++) {
            cin >> s;
            h = s[0] - 'a', t = s[s.size() - 1] - 'a';
            pre[h]++;
            suf[t]++;
            g[h].push_back(t);
            g[t].push_back(h);
        }

        if (graph_num() != 1) cout << "NG\n";
        else {
            if (equal(begin(pre), end(pre), begin(suf))) cout << "OK\n";
            else cout << "NG\n";
        }
    }
}

