#include <iostream>
#include <array>
using namespace std;

bool visit[26];
array<array<int, 26>, 26> g;

bool dfs(int v) {
    visit[v] = true;
    bool f = false;

    for (int i = 0; i < 26; i++) {
        if (g[v][i] && !visit[i]) {
            f = true;
            f |= dfs(i);
        }
    }
    return f;
}

int graph_num(void) {
    int res = 0;
    for (int i = 0; i < 26; i++)
        if (!visit[i] && dfs(i)) res++;
    return res;
}

int main() {
    int n, pre[26], suf[26], h, t;
    string s;

    while (cin >> n && n) {
        fill(begin(visit), end(visit), false);
        fill(begin(pre), end(pre), 0);
        fill(begin(suf), end(suf), 0);

        g.fill(array<int, 26>{}); // clear the adjacency list

        for (int i = 0; i < n; i++) {
            cin >> s;
            h = s[0] - 'a', t = s[s.size() - 1] - 'a';
            pre[h]++;
            suf[t]++;
            g[h][t] = 1; // set edge for h -> t
            g[t][h] = 1; // set edge for t -> h
        }

        if (graph_num() != 1) cout << "NG\n";
        else {
            bool equal = true;
            for (int i = 0; i < 26; i++) {
                if (pre[i] != suf[i]) {
                    equal = false;
                    break;
                }
            }
            cout << (equal ? "OK\n" : "NG\n");
        }
    }
}

