#include <iostream>
#include <vector>
#include <stack>
using namespace std;

bool visit[26];
vector<int> g[26]; // adjacency list

bool dfs(int v) {
    stack<int> s;
    s.push(v);
    visit[v] = true;
    bool f = false;

    while (!s.empty()) {
        int node = s.top();
        s.pop();
        for (int i : g[node]) {
            if (!visit[i]) {
                visit[i] = true;
                s.push(i);
                f = true;
            }
        }
    }
    return f;
}

int graph_num(void) {
    int res = 0;
    for (int i = 0; i < 26; i++)
        if (!visit[i] && dfs(i)) res++;
    return res;
